-- Fakt kartochkalarining ruscha matni — 18-partiya:
-- Tamara Xonim, Halima Nosirova, Mukarrama Turg'unboyeva.

-- ===== Tamara Xonim =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Каково настоящее имя Тамары Ханум и где она родилась?', fact_ru = 'Я появилась на свет в 1906 году в городе Фергана, в рабочей армянской семье. Моё настоящее имя — Тамара Артёмовна Петросян, но народ знает меня как Тамару Ханум.' WHERE id = 537;
UPDATE fact_cards SET topic_ru = 'Единственная женщина в ансамбле', question_ru = 'Сколько женщин было в ансамбле 1920 года?', fact_ru = 'В ансамбле, созданном в 1920 году народным певцом Мухиддином Кариякубовым, из женщин была только я — в ту пору выход женщины на сцену считался большой смелостью.' WHERE id = 538;
UPDATE fact_cards SET topic_ru = 'Первая ласточка Востока', question_ru = 'Как называли Тамару Ханум?', fact_ru = 'С юных лет я участвовала в музыкально-драматических спектаклях как артистка, певица и танцовщица, и уже в 1924 году меня назвали «первой ласточкой Востока».' WHERE id = 539;
UPDATE fact_cards SET topic_ru = 'Учебник вместе с наставником', question_ru = 'Какой учебник создала Тамара Ханум вместе со своим наставником?', fact_ru = 'Вместе с моим наставником Устой Олимом Комиловым в 1927–1928 годах мы создали учебник движений рук и ног из 120 приёмов — это стало важным шагом в обучении узбекскому танцу.' WHERE id = 540;
UPDATE fact_cards SET topic_ru = 'Танцевальная труппа в театре', question_ru = 'В каком театре Тамара Ханум возглавляла танцевальную труппу?', fact_ru = 'В государственном узбекском музыкальном театре, созданном в 1929 году, танцевальную труппу возглавляла я — позже этот театр стал большим театром имени Алишера Навои.' WHERE id = 541;
UPDATE fact_cards SET topic_ru = 'Золотая медаль в Лондоне', question_ru = 'На фестивале в каком городе Тамара Ханум получила золотую медаль?', fact_ru = 'На первом международном фестивале танцевального и музыкального искусства, прошедшем в 1935 году в Лондоне, мы вместе с Устой Олимом Комиловым показали неведомое миру узбекское искусство и удостоились золотой медали.' WHERE id = 542;
UPDATE fact_cards SET topic_ru = 'В годы войны', question_ru = 'Что делала Тамара Ханум в годы войны?', fact_ru = 'В годы Второй мировой войны я участвовала во фронтовых концертных бригадах — узбекские артисты поддерживали бойцов духом и дали на фронтах более 35 тысяч концертов.' WHERE id = 543;
UPDATE fact_cards SET topic_ru = 'Песни 86 народов', question_ru = 'Песнями скольких народов обогатилась творческая сокровищница Тамары Ханум?', fact_ru = 'Я представляла узбекское искусство в Индии, Афганистане, Индонезии и Пакистане и сама собирала там песни и танцы — моя творческая сокровищница обогатилась песнями и танцами 86 народов мира.' WHERE id = 544;
UPDATE fact_cards SET topic_ru = 'Мой дом-музей', question_ru = 'Когда был устроен мемориальный музей Тамары Ханум?', fact_ru = 'Я скончалась в 1991 году. После моей смерти, в 1994 году, в моём ташкентском доме был устроен мемориальный музей — там хранятся мои сценические наряды, награды, фотографии и письма, написанные мне.' WHERE id = 545;
UPDATE fact_cards SET topic_ru = 'Память обо мне', question_ru = 'Где отмечалось 120-летие Тамары Ханум?', fact_ru = 'Я скончалась в 1991 году. В 2026 году 120-летие со дня моего рождения было отмечено большим концертом в театре имени Алишера Навои.' WHERE id = 546;
UPDATE fact_cards SET topic_ru = 'Парижская выставка', question_ru = 'На Всемирной выставке в каком городе Тамара Ханум исполнила узбекский танец в 1925 году?', fact_ru = 'На Всемирной выставке, прошедшей в 1925 году в Париже, я исполнила узбекский танец. Европейские зрители встретили наше искусство громом рукоплесканий.' WHERE id = 1793;
UPDATE fact_cards SET topic_ru = 'Мои звания', question_ru = 'Какого высокого звания удостоилась Тамара Ханум в 1956 году?', fact_ru = 'За заслуги в искусстве я получила звание народной артистки Узбекистана, а в 1956 году удостоилась звания народной артистки СССР.' WHERE id = 1794;
UPDATE fact_cards SET topic_ru = 'На мировых сценах', question_ru = 'Где Тамара Ханум представляла узбекское искусство?', fact_ru = 'С гастролями я побывала во многих странах мира и представляла узбекскую песню и танец на сценах разных материков.' WHERE id = 1795;
UPDATE fact_cards SET topic_ru = 'Мои соратники', question_ru = 'Какому ансамблю положила начало Мукаррама Тургунбаева, соратница Тамары Ханум?', fact_ru = 'Уста Олим Комилов и Мукаррама Тургунбаева были моими близкими соратниками. Мукаррама позже положила начало знаменитому ансамблю «Бахор».' WHERE id = 1796;
UPDATE fact_cards SET topic_ru = 'Мои ученики', question_ru = 'Что делала Тамара Ханум для молодых артистов?', fact_ru = 'Я была наставницей молодых танцовщиц и певиц. Мои ученики продолжили традиции узбекского сценического искусства.' WHERE id = 1797;
UPDATE fact_cards SET topic_ru = 'Моя работа в филармонии', question_ru = 'В каком учреждении Тамара Ханум много лет работала солисткой?', fact_ru = 'Много лет я работала солисткой Государственной филармонии Узбекистана.' WHERE id = 1798;
UPDATE fact_cards SET topic_ru = 'Своеобразие моего искусства', question_ru = 'В чём было своеобразие творческой манеры Тамары Ханум?', fact_ru = 'На сцене я исполняла песню и танец слитно: петь и одновременно танцевать стало моей творческой манерой.' WHERE id = 1799;

-- ===== Halima Nosirova =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родилась Халима Насырова?', fact_ru = 'Я родилась в 1913 году в селении Таглик близ Коканда.' WHERE id = 547;
UPDATE fact_cards SET topic_ru = 'Годы моей учёбы', question_ru = 'В театральное училище какого города была направлена Халима Насырова?', fact_ru = 'Учась в женском училище в Ташкенте, я ходила в кружок художественной самодеятельности, а затем вместе с группой молодых артистов была направлена на учёбу в театральное училище в Баку.' WHERE id = 548;
UPDATE fact_cards SET topic_ru = 'Оперная студия в Москве', question_ru = 'Где Халима Насырова обучалась оперному искусству?', fact_ru = 'Я обучалась в Узбекской оперной студии при Московской государственной консерватории — она открыла мне тайны оперного искусства.' WHERE id = 549;
UPDATE fact_cards SET topic_ru = 'Спектакль «Халима»', question_ru = 'Сколько раз Халима Насырова исполнила главную роль в спектакле «Халима»?', fact_ru = 'Главную роль в спектакле Гулама Зафари «Халима» я исполнила более пятисот раз и всякий раз удостаивалась рукоплесканий зрителей.' WHERE id = 550;
UPDATE fact_cards SET topic_ru = 'Первая узбекская опера', question_ru = 'Как называется первая узбекская опера и когда она была поставлена?', fact_ru = 'На премьере первой узбекской оперы «Буран» 11 июня 1939 года я пела партию Наргуль. С этого года я работала в театре оперы и балета имени Алишера Навои.' WHERE id = 551;
UPDATE fact_cards SET topic_ru = 'Мои знаменитые роли', question_ru = 'В каких операх Халима Насырова создала главные образы?', fact_ru = 'Я создала главные образы в десятках опер — «Лейли и Меджнун», «Гульсара», «Кармен», «Проделки Майсары», «Зайнаб и Аман», «Улугбек»; партия Син Дун Фан в опере «Улугбек» стала моей творческой удачей.' WHERE id = 552;
UPDATE fact_cards SET topic_ru = 'Народные песни', question_ru = 'Какие народные песни пела Халима Насырова?', fact_ru = 'Такие народные песни, как «Ушшок», «Чоргох», «Баёт», я пела в собственной манере; напевам и песням я училась у таких наставников, как Мулла Туйчи Ташмухаммедов и Уста Олим Комилов.' WHERE id = 553;
UPDATE fact_cards SET topic_ru = 'В годы войны', question_ru = 'Что делала Халима Насырова в годы войны?', fact_ru = 'В годы Второй мировой войны я, как и другие артисты, выступала перед бойцами в составе концертных бригад.' WHERE id = 554;
UPDATE fact_cards SET topic_ru = 'Кино и мировые сцены', question_ru = 'В каких фильмах снималась Халима Насырова?', fact_ru = 'Я сыграла роли в фильмах «Асаль», «Подарок фронту», «Ты мне очарование»; мой голос звучал в десятках стран — в Индии, Бирме, Ливане, Египте, Иране, Китае и Канаде, а в 1956 году сирийские и индийские газеты писали о моём голосе с похвалой.' WHERE id = 555;
UPDATE fact_cards SET topic_ru = 'Мои звания и моя книга', question_ru = 'Как называется книга воспоминаний Халимы Насыровой?', fact_ru = 'Я удостоилась звания «Народная артистка Узбекистана», а в годы независимости была награждена орденом «За выдающиеся заслуги»; есть у меня и книга воспоминаний под названием «Я — узбекская девушка». Я скончалась в 2003 году в Ташкенте. Сегодня международный конкурс молодых оперных исполнителей носит моё имя.' WHERE id = 556;
UPDATE fact_cards SET topic_ru = 'Мои первые годы на сцене', question_ru = 'Где начала работать Халима Насырова, вернувшись из Баку?', fact_ru = 'Вернувшись после учёбы в Баку, я начала работать актрисой в узбекском музыкально-драматическом театре в Ташкенте.' WHERE id = 1609;
UPDATE fact_cards SET topic_ru = 'В театре Навои', question_ru = 'В каком театре Халима Насырова была солисткой?', fact_ru = 'Многие годы я служила солисткой в театре оперы и балета имени Алишера Навои.' WHERE id = 1610;
UPDATE fact_cards SET topic_ru = 'Моя партия Лейли', question_ru = 'Какую партию пела Халима Насырова в опере «Лейли и Меджнун»?', fact_ru = 'В опере «Лейли и Меджнун» я пела партию главной героини — Лейли.' WHERE id = 1611;
UPDATE fact_cards SET topic_ru = 'Моя роль в «Гульсаре»', question_ru = 'Какую роль играла Халима Насырова в музыкальной драме «Гульсара»?', fact_ru = 'В музыкальной драме «Гульсара» я исполняла главную роль — образ Гульсары.' WHERE id = 1612;
UPDATE fact_cards SET topic_ru = 'Моя оперная школа', question_ru = 'Почему Халиму Насырову называют первой звездой узбекской оперы?', fact_ru = 'В узбекском оперном искусстве я создала собственную исполнительскую школу. Потому меня и называют «первой звездой узбекской оперы».' WHERE id = 1613;
UPDATE fact_cards SET topic_ru = 'Певица и актриса', question_ru = 'В каких видах искусства творила Халима Насырова?', fact_ru = 'Я была и певицей, и актрисой: пела на оперной сцене, играла роли в спектаклях и кино.' WHERE id = 1614;
UPDATE fact_cards SET topic_ru = 'Мой долгий век', question_ru = 'Сколько лет прожила Халима Насырова?', fact_ru = 'Я прожила девяносто лет и ушла из жизни в 2003 году. А песни мои звучат до сих пор.' WHERE id = 1615;

-- ===== Mukarrama Turg'unboyeva =====
UPDATE fact_cards SET topic_ru = 'Моё детство', question_ru = 'Когда и где родилась Мукаррама Тургунбаева?', fact_ru = 'Я родилась в 1913 году под Ферганой, в семье среднего достатка. Отец умер, когда я была совсем мала; я воспитывалась в доме дяди и училась в педагогическом техникуме.' WHERE id = 566;
UPDATE fact_cards SET topic_ru = 'Обет служить искусству', question_ru = 'Чей танец увидела Мукаррама Тургунбаева и дала обет стать артисткой?', fact_ru = 'В техникуме я ходила в кружок пения и танца. Увидев танец Тамары Ханум «Дильхирадж», я была глубоко потрясена и твёрдо решила стать артисткой.' WHERE id = 567;
UPDATE fact_cards SET topic_ru = 'В театральной студии', question_ru = 'У кого Мукаррама Тургунбаева училась узбекскому танцу?', fact_ru = 'В 1929–1933 годах я была актрисой и ученицей Первой Узбекской государственной музыкальной театральной студии; узбекскому танцу я училась у Усты Олима Комилова и Тамары Ханум.' WHERE id = 568;
UPDATE fact_cards SET topic_ru = 'Моё преподавание', question_ru = 'По какому пособию Мукаррамы Тургунбаевой преподают узбекский танец?', fact_ru = 'С 1933 года я работала преподавательницей в Республиканской балетной школе; по нашему с наставником Устой Олимом Комиловым пособию «Урок дойры и танец» узбекский танец преподают до сих пор.' WHERE id = 569;
UPDATE fact_cards SET topic_ru = 'Мои роли на сцене', question_ru = 'Первой исполнительницей какого танца была Мукаррама Тургунбаева?', fact_ru = 'Я первая исполнительница танца «Тановар»; в 1939 году я исполнила главную роль в балете «Шахида», а в 1943 году — в балете «Акбилак».' WHERE id = 570;
UPDATE fact_cards SET topic_ru = 'Вдохновение от «Берёзки»', question_ru = 'Как у Мукаррамы Тургунбаевой появилась мечта создать девичий ансамбль?', fact_ru = 'В 1956 году на международном фестивале молодёжи в Москве я увидела ансамбль «Берёзка», и у меня родилась мечта создать и в Узбекистане ансамбль национального танца из одних девушек.' WHERE id = 571;
UPDATE fact_cards SET topic_ru = 'Рождение «Бахора»', question_ru = 'Когда был создан ансамбль «Бахор» и откуда взято его название?', fact_ru = 'В 1957 году я собрала труппу из 12 девушек, которым сама преподавала в Ташкентском хореографическом училище, и лучших певцов и музыкантов — в честь мелодии композитора М. Мирзаева «Весенний вальс» ансамбль назвали «Бахор».' WHERE id = 572;
UPDATE fact_cards SET topic_ru = '600 танцев', question_ru = 'Сколько танцев поставила Мукаррама Тургунбаева?', fact_ru = 'С 1957 года и до конца жизни я была художественным руководителем «Бахора»: я поставила около 600 национальных танцев и танцев народов мира, а наш ансамбль выступил более чем в 50 странах.' WHERE id = 573;
UPDATE fact_cards SET topic_ru = 'Мои награды', question_ru = 'Какой конкурс проводится в память о Мукарраме Тургунбаевой?', fact_ru = 'Мои труды отмечены званием «Народная артистка» и рядом орденов и медалей; в память обо мне каждый год 31 мая проводится республиканский смотр-конкурс «Танцовщица года».' WHERE id = 574;
UPDATE fact_cards SET topic_ru = 'Моё наследие', question_ru = 'Когда был вновь учреждён государственный танцевальный ансамбль «Бахор»?', fact_ru = 'Я скончалась в 1978 году. В феврале 2020 года постановлением Президента был вновь учреждён государственный танцевальный ансамбль «Бахор» имени Мукаррамы Тургунбаевой — обо мне говорят, что я «оставила после себя живой памятник».' WHERE id = 575;
UPDATE fact_cards SET topic_ru = 'Мой танец «Тановар»', question_ru = 'Какой древний узбекский танец прославился в исполнении Мукаррамы Тургунбаевой?', fact_ru = 'Танец на основе древней народной мелодии «Тановар» был одним из самых любимых моих танцев. Я много раз исполняла его на сцене, и этот танец связан с моим именем.' WHERE id = 1709;
UPDATE fact_cards SET topic_ru = 'Мой танец «Пахта»', question_ru = 'Какой танец создала Мукаррама Тургунбаева, посвятив его труду хлопкоробов?', fact_ru = 'Я мечтала показать в танце труд девушек-хлопкоробов. Так родился танец «Пахта» — в нём труд хлопкоробов выражен изящными движениями танца.' WHERE id = 1710;
UPDATE fact_cards SET topic_ru = 'В оперном театре', question_ru = 'В каком театре Мукаррама Тургунбаева работала балетмейстером?', fact_ru = 'Я работала в театре оперы и балета имени Алишера Навои в Ташкенте. Там я танцевала сама и как балетмейстер ставила танцы в спектаклях.' WHERE id = 1711;
UPDATE fact_cards SET topic_ru = 'На мировых сценах', question_ru = 'Где выступал ансамбль «Бахор» Мукаррамы Тургунбаевой?', fact_ru = 'С ансамблем «Бахор» мы выступали во многих странах мира. Изящные танцы наших девушек познакомили с узбекским искусством весь свет.' WHERE id = 1712;
UPDATE fact_cards SET topic_ru = 'Узбекская школа танца', question_ru = 'Одной из основательниц какой школы искусства считается Мукаррама Тургунбаева?', fact_ru = 'Меня называют одной из основательниц узбекской школы национального танца. Всю свою жизнь я посвятила тому, чтобы поднять искусство танца на высокий профессиональный уровень.' WHERE id = 1713;
UPDATE fact_cards SET topic_ru = 'Три школы танца', question_ru = 'Какие школы танца включила Мукаррама Тургунбаева в программы «Бахора»?', fact_ru = 'В программы «Бахора» мы включали танцы ферганской, хорезмской и бухарской школ. У каждой школы свои особые тонкие движения и своё обаяние.' WHERE id = 1714;
UPDATE fact_cards SET topic_ru = 'Ансамбль моего имени', question_ru = 'Какому ансамблю после смерти Мукаррамы Тургунбаевой было присвоено её имя?', fact_ru = 'Я ушла из жизни в 1978 году. В признание моих заслуг после моей смерти любимому ансамблю «Бахор» было присвоено моё имя.' WHERE id = 1715;
